"""Write the generated files.

    models/<name>/model.sdf, model.config      the Gazebo model
    config/<name>_bridge.yaml                  ros_gz_bridge topic list
    config/<name>_frames.yaml                  static TF frames for the launch file
    config/<name>_report.txt / _report.json    design report, text and machine-readable
"""
import json
import os

import yaml

from .sdf_model import to_sdf, model_config
from .sensors import BridgeTopic

HEADER = '# GENERATED by asvgen (fingerprint {fp}) - edit config/asv.yaml instead.\n'


def bridge_topics(boat):
    ns = boat.cfg['namespace']
    topics = [BridgeTopic('/clock', 'rosgraph_msgs/msg/Clock', 'gz.msgs.Clock'),
              BridgeTopic(f'/{ns}/ground_truth/odom', 'nav_msgs/msg/Odometry', 'gz.msgs.Odometry')]
    for part in boat.parts:
        topics += part.bridge
    for side in ('left', 'right'):
        for what in ('thrust', 'pos'):
            topics.append(BridgeTopic(f'/{ns}/thrusters/{side}/{what}', 'std_msgs/msg/Float64',
                                      'gz.msgs.Double', 'ROS_TO_GZ'))
    names = [t.topic for t in topics]
    duplicates = {n for n in names if names.count(n) > 1}
    if duplicates:
        raise SystemExit(f'ERROR: duplicate topics {sorted(duplicates)} - sensor names must differ')
    return topics


def bridge_yaml(boat):
    entries = [{'ros_topic_name': t.topic, 'gz_topic_name': t.topic, 'ros_type_name': t.ros_type,
                'gz_type_name': t.gz_type, 'direction': t.direction} for t in bridge_topics(boat)]
    return HEADER.format(fp=boat.fingerprint) + yaml.safe_dump(entries, sort_keys=False)


def frames_yaml(boat):
    frames = [{'parent': f.parent, 'child': f.child,
               'xyz': [round(float(v), 6) for v in f.xyz], 'rpy': [round(float(v), 6) for v in f.rpy]}
              for part in boat.parts for f in part.frames]
    children = [f['child'] for f in frames]
    if len(children) != len(set(children)):
        raise SystemExit('ERROR: two TF frames with the same name - sensor names must differ')
    return HEADER.format(fp=boat.fingerprint) + yaml.safe_dump({'frames': frames}, sort_keys=False,
                                                               default_flow_style=None)


def write_all(boat, metrics, report_text, pkg_dir):
    name = boat.cfg['name']
    model_dir = os.path.join(pkg_dir, 'models', name)
    cfg_dir = os.path.join(pkg_dir, 'config')
    os.makedirs(model_dir, exist_ok=True)
    os.makedirs(cfg_dir, exist_ok=True)
    files = {
        os.path.join(model_dir, 'model.sdf'): to_sdf(boat),
        os.path.join(model_dir, 'model.config'): model_config(boat),
        os.path.join(cfg_dir, f'{name}_bridge.yaml'): bridge_yaml(boat),
        os.path.join(cfg_dir, f'{name}_frames.yaml'): frames_yaml(boat),
        os.path.join(cfg_dir, f'{name}_report.txt'): report_text + '\n',
        os.path.join(cfg_dir, f'{name}_report.json'): json.dumps(metrics, indent=2) + '\n',
    }
    for path, text in files.items():
        with open(path, 'w') as f:
            f.write(text)
    return [os.path.relpath(p, pkg_dir) for p in files]
